const api = import.meta.env.VITE_API_BASE_URL || '/api';
const tz = import.meta.env.VITE_DISPLAY_TIMEZONE || 'Europe/Istanbul';
const get = async <T,>(path: string): Promise<T> => { const response = await fetch(`${api}${path}`); if (!response.ok) throw new Error(`API request failed (${response.status})`); return response.json(); };
const date = (value?: string | null) => value ? new Intl.DateTimeFormat('tr-TR', { timeZone: tz, dateStyle: 'short', timeStyle: 'medium' }).format(new Date(value)) : 'N/A';
const mb = (value?: number | null) => value == null ? 'N/A' : `${value.toLocaleString('en-US', { maximumFractionDigits: 1 })} MB`;
type Overview = { totalServers:number; totalDatabases:number; onlineDatabases:number; warningDatabases:number; offlineDatabases:number; lastCollectionStatus?:string; lastCollectionStartedAtUtc?:string; lastCollectionFinishedAtUtc?:string; lastCollectionDurationMs?:number; collectionErrorCount:number };
type Health = { databaseId:number; databaseName:string; serverName:string; databaseStatus:string; recoveryModel:string; lastSeenAtUtc:string; healthStatus:string };
type Capacity = { summary:{totalDataSizeMb:number; totalLogSizeMb:number; totalDatabaseSizeMb:number}; items:{databaseId:number;databaseName:string;dataSizeMb:number;logSizeMb:number;totalSizeMb:number}[] };
type Collection = { collectionRunId:number; startedAtUtc:string; finishedAtUtc?:string; status:string; durationMs?:number; errorCount:number };
type Server = { serverId:number; serverName:string; instanceName:string; sqlVersion:string; edition:string; databaseCount:number; lastSeenAtUtc:string; isActive?:boolean };
type ServerDb = { databaseId:number; databaseName:string; databaseStatus:string; recoveryModel:string; lastSeenAtUtc:string };
type Database = { databaseId:number; databaseName:string; serverId:number; serverName:string; databaseStatus:string; recoveryModel:string; lastSeenAtUtc:string; currentDataSizeMb?:number; currentLogSizeMb?:number; currentTotalSizeMb?:number; lastFullBackupAtSource?:string };
type Detail = Database & { lastDifferentialBackupAtSource?:string; lastLogBackupAtSource?:string };
type Point = { collectedAtUtc:string; dataSizeMb:number; logSizeMb:number; totalSizeMb:number };
type Audit = { id:number; occurredAtUtc:string; userName:string; userRole?:string; action:string; resourceType:string; resourceId?:string; httpMethod:string; requestPath:string; result:string; statusCode:number; durationMs:number; correlationId:string; clientIp?:string; userAgent?:string; additionalData?:string };
type PerformanceOverview = { blockingObservationCount:number; maxBlockingDurationMs:number; deadlockCount:number; longRunningObservationCount:number; lastPerformanceCollectionAtUtc?:string };
type Blocking = { id:number; capturedAtUtc:string; serverName:string; databaseName?:string; sessionId:number; blockingSessionId:number; waitType?:string; waitDurationMs:number; command?:string; applicationName?:string; sqlTextPreview?:string };
type Deadlock = { id:number; occurredAtUtc:string; serverName:string; databaseName?:string; victimProcessId?:string; processCount:number; deadlockHash:string };
type LongRunning = { id:number; capturedAtUtc:string; serverName:string; databaseName?:string; sessionId:number; elapsedMs:number; status?:string; command?:string; waitType?:string; cpuTimeMs?:number; reads?:number; applicationName?:string; sqlTextPreview?:string };
type Wait = { waitType:string; waitTimeDeltaMs:number; signalWaitDeltaMs:number; waitingTasksDelta:number; percentage:number };
type OperationsOverview = { activeEventCount:number; activeCriticalCount:number; activeWarningCount:number; resolvedEventCount:number; blockingEventCount:number; longRunningEventCount:number; deadlockEventCount:number };
type OperationalEvent = { id:number; eventType:string; serverName:string; databaseName?:string; fingerprint:string; startedAtUtc:string; lastSeenAtUtc:string; endedAtUtc?:string; durationMs:number; status:string; severity:string; observationCount:number; affectedSessionCount?:number; title:string; summary:string };
type OperationalDetail = OperationalEvent & { createdAtUtc:string; updatedAtUtc:string; additionalData?:string; sourceEntityId?:number };
type ProtectionOverview = { protectedDatabaseCount:number; backupWarningCount:number; backupCriticalCount:number; backupUnknownCount:number; alwaysOnHealthyCount:number; alwaysOnWarningCount:number; alwaysOnCriticalCount:number; failedJobCount:number; runningJobCount:number; longRunningJobCount:number };
type BackupProtection = { databaseId:number; databaseName:string; serverName:string; recoveryModel:string; databaseState:string; protectionStatus:string; lastFullBackupAtSource?:string; lastDifferentialBackupAtSource?:string; lastLogBackupAtSource?:string; backupAgeMinutes?:number; logBackupAgeMinutes?:number; lastCollectedAtUtc?:string; dataFreshness:string };
type AlwaysOnHealth = { id:number; serverName:string; availabilityGroupName:string; replicaServerName?:string; role?:string; connectedState?:string; synchronizationHealth?:string; databaseName?:string; synchronizationState?:string; isSuspended:boolean; logSendQueueMb?:number; redoQueueMb?:number; collectedAtUtc:string; healthStatus:string; dataFreshness:string };
type JobHealth = { id:number; serverName:string; jobId:string; jobName:string; enabled:boolean; lastRunStatus:string; lastRunAtSource?:string; lastRunDurationSeconds?:number; isRunning:boolean; currentDurationSeconds?:number; failureCount24Hours:number; failureCount7Days:number; repeatedFailure:boolean; isLongRunning:boolean; collectedAtUtc:string; dataFreshness:string };
type Page<T> = { items:T[]; page:number; pageSize:number; totalCount:number };
type CapacityOverview = { totalDatabaseSizeMb:number; growth30dMb:number; databaseWarningCount:number; databaseCriticalCount:number; volumeWarningCount:number; volumeCriticalCount:number; forecastableDatabaseCount:number; insufficientDataCount:number; nearestExhaustionDays?:number };
type CapacityDb = { databaseId:number; databaseName:string; serverName:string; currentDataSizeMb:number; currentLogSizeMb:number; currentTotalSizeMb:number; growth7dMb?:number; growth30dMb?:number; growth90dMb?:number; growthRateMbPerDay?:number; forecast30dMb?:number; forecast90dMb?:number; rSquared?:number; sampleCount:number; historyDays:number; forecastStatus:string; capacityStatus:string; lastCollectedAtUtc?:string; dataFreshness:string };
type VolumeCapacity = { id:number; serverId:number; serverName:string; volumeId:string; totalBytes:number; availableBytes:number; freePercent:number; growthBytesPerDay?:number; estimatedExhaustionDays?:number; forecastStatus:string; capacityStatus:string; sampleCount:number; collectedAtUtc:string; dataFreshness:string };
type CapacityPoint = { collectedAtUtc:string; dataSizeMb:number; logSizeMb:number; totalSizeMb:number; forecastTotalSizeMb?:number; seriesType:string };
type AnomalyOverview = { activeAnomalyCount:number; activeCriticalCount:number; activeWarningCount:number; resolvedAnomalyCount:number; usableBaselineCount:number; insufficientBaselineCount:number; entitiesWithAnomalies:number };
type AnomalyRow = { id:number; metricType:string; serverName:string; databaseName?:string; entityKey?:string; observedAtUtc:string; observedValue:number; baselineMedian:number; baselineP95:number; deviationRatio?:number; modifiedZScore?:number; baselineScope:string; sampleCount:number; severity:string; status:string; explanationCode:string; startedAtUtc:string; lastSeenAtUtc:string };
type AnomalyDetail = AnomalyRow & { baselineP99:number; baselineMad:number; windowDays:number; endedAtUtc?:string; observationCount:number; sourceEntityId?:number; fingerprint:string };

const statusColor = (status: string) => status === 'Healthy' || status === 'Success' || status === 'ONLINE' ? 'success' : status === 'Critical' || status === 'Failed' ? 'error' : 'warning';
function Metric({ label, value, tone }: {label:string; value:string|number; tone?: 'success'|'warning'|'error'}) { return <KpiCard title={label} value={value} tone={tone} />; }function exportXlsx(filename: string, rows: unknown[]) {
  if (!rows.length) return;
  const records = rows.map(row => row && typeof row === 'object' ? row as Record<string, unknown> : { value: row });
  const worksheet = XLSX.utils.json_to_sheet(records);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'Data');
  XLSX.writeFile(workbook, `${filename}.xlsx`);
}
function ListTools({ filename, rows, pageSize, onPageSizeChange }: { filename: string; rows: unknown[]; pageSize: number; onPageSizeChange: (size: number) => void }) {
  return <Stack direction="row" spacing={1} alignItems="center" justifyContent="flex-end" flexWrap="wrap" useFlexGap sx={{ my: 1 }}><Typography variant="caption" color="text.secondary">Kayıt</Typography><Select size="small" value={pageSize} onChange={event => onPageSizeChange(Number(event.target.value))}>{[10, 20, 30, 40, 50].map(size => <MenuItem key={size} value={size}>{size}</MenuItem>)}</Select><Button size="small" variant="outlined" onClick={() => exportXlsx(filename, rows)}>Excel'e Aktar</Button></Stack>;
}
function State({ value }: {value:string}) { return <StatusChip value={value} />; }
type ServerCardModel = Server & { items: Database[]; critical: number; warning: number; healthy: number; status: 'Critical' | 'Warning' | 'Healthy'; totalSize: number };
function RackServerCard({server,onServer}:{server:ServerCardModel;onServer:(id:number)=>void}) {
 const led=server.status==='Healthy'?'good':server.status==='Warning'?'warn':'bad'; const ageHours=Math.max(0,(Date.now()-new Date(server.lastSeenAtUtc).getTime())/3600000); const freshness=ageHours<1?'Fresh':ageHours<3?'Aging':'Stale';
 return <Paper className={`rack-server server-${server.status.toLowerCase()} clickable`} onClick={()=>onServer(server.serverId)}><Box className="rack-server-face"><Stack direction="row" justifyContent="space-between" alignItems="center" className="rack-server-top"><Stack direction="row" spacing={1.2} alignItems="center"><Box className={`rack-status-led ${led}`}/><Box><Typography className="rack-server-name" noWrap title={server.serverName}>{server.serverName}</Typography><Typography className="rack-server-subtitle" noWrap>{server.instanceName} · {server.edition}</Typography></Box></Stack></Stack><Box className="rack-server-console"><Box className="rack-display"><Typography className="rack-display-title">{server.status.toUpperCase()}</Typography><Typography className="rack-display-meta">SQL {server.sqlVersion}</Typography></Box><Box className="rack-led-bank"><Box><span className="mini-led good"/><Typography>PWR</Typography></Box><Box><span className={`mini-led ${led}`}/><Typography>STAT</Typography></Box><Box><span className="mini-led info"/><Typography>NET</Typography></Box></Box></Box><Box className="rack-server-info"><Box className="server-card-metrics"><Box><Typography className="server-metric-value">{server.items.length}</Typography><Typography className="server-metric-label">DB toplam</Typography></Box><Box><Typography className="server-metric-value server-good">{server.healthy}</Typography><Typography className="server-metric-label">Sağlıklı</Typography></Box><Box><Typography className="server-metric-value server-warn">{server.warning}</Typography><Typography className="server-metric-label">Uyarı</Typography></Box><Box><Typography className="server-metric-value server-bad">{server.critical}</Typography><Typography className="server-metric-label">Kritik</Typography></Box></Box><Box className="rack-health-bands"><Box className={`health-band ${led}`}><Typography>DB HEALTH</Typography><b>{server.healthy}/{server.items.length}</b></Box><Box className={`health-band ${server.totalSize>30000?"warn":"good"}`}><Typography>CAPACITY</Typography><b>{mb(server.totalSize)}</b></Box><Box className={`health-band ${freshness.toLowerCase()}`}><Typography>COLLECTOR</Typography><b>{freshness}</b></Box><Box className="health-band info"><Typography>ENGINE</Typography><b>{server.sqlVersion.split(".")[0]}</b></Box></Box><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{mt:1.5}}><Typography variant="body2" color="text.secondary">{mb(server.totalSize)} toplam kapasite</Typography><Typography variant="caption" color="text.secondary">{date(server.lastSeenAtUtc)}</Typography></Stack><Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap sx={{mt:1.25}}>{server.items.slice(0,5).map(db=><Chip key={db.databaseId} size="small" variant="outlined" label={db.databaseName} color={db.databaseStatus==='ONLINE'?'success':server.critical?'error':'warning'}/>)}{server.items.length>5&&<Chip size="small" label={`+${server.items.length-5} DB`}/>}</Stack></Box></Box></Paper>;
}
function ServerFleet({ servers, onServer }: { servers: ServerCardModel[]; onServer: (id: number) => void }) {
 const [zoom,setZoom]=useState(0.9); const clamp=(value:number)=>Math.min(1.35,Math.max(0.65,value));
 return <Box className="fleet-map"><Stack direction="row" justifyContent="space-between" alignItems="center" className="fleet-toolbar"><Box /><Stack direction="row" spacing={.5} alignItems="center"><IconButton size="small" aria-label="Uzaklaştır" onClick={()=>setZoom(z=>clamp(z-.1))}><RemoveIcon fontSize="small"/></IconButton><Typography variant="caption" className="zoom-label">{Math.round(zoom*100)}%</Typography><IconButton size="small" aria-label="Yakınlaştır" onClick={()=>setZoom(z=>clamp(z+.1))}><AddIcon fontSize="small"/></IconButton><IconButton size="small" aria-label="Yakınlaştırmayı sıfırla" onClick={()=>setZoom(.9)}><CenterFocusStrongIcon fontSize="small"/></IconButton></Stack></Stack><Box className="fleet-map-viewport"><Box className="fleet-map-canvas" sx={{transform:`scale(${zoom})`}}>{servers.map(server=><RackServerCard key={server.serverId} server={server} onServer={onServer}/>)}</Box></Box></Box>;
}type ManagementOverview = {serverCount:number;databaseCount:number;criticalEntityCount:number;warningEntityCount:number;attentionEntityCount:number;unknownEntityCount:number;activeOperationalEvents:number;activeAnomalies:number;relatedSignalGroups:number;newCritical24h:number;resolved24h:number;summary:string};
type ManagementAttention = {id:number;severity:string;serverName:string;databaseName?:string;domain:string;issue:string;startedAtUtc:string;lastSeenAtUtc:string;relatedSignalCount:number;explanationCode:string};
type ManagementHealth = {entityType:string;serverId:number;databaseId?:number;serverName:string;databaseName?:string;overallStatus:string;performanceStatus:string;protectionStatus:string;availabilityStatus:string;capacityStatus:string;anomalyStatus:string;freshnessStatus:string};function ManagementDashboard({onDatabase,onServer}:{onDatabase:(id:number)=>void;onServer:(id:number)=>void}) {
 const [o,setO]=useState<ManagementOverview>(); const [a,setA]=useState<Page<ManagementAttention>>(); const [h,setH]=useState<ManagementHealth[]>([]); const [servers,setServers]=useState<Server[]>(); const [dbs,setDbs]=useState<Database[]>(); const [collection,setCollection]=useState<Overview>(); const [error,setError]=useState('');
 useEffect(()=>{Promise.all([get<ManagementOverview>('/management/overview'),get<Page<ManagementAttention>>('/management/attention?page=1&pageSize=25'),get<ManagementHealth[]>('/management/health'),get<Server[]>('/servers'),get<{items:Database[]}>('/databases?page=1&pageSize=100'),get<Overview>('/dashboard/overview')]).then(([ov,att,health,serverRows,databaseRows,collectionOverview])=>{setO(ov);setA(att);setH(health);setServers(serverRows);setDbs(databaseRows.items);setCollection(collectionOverview)}).catch(e=>setError(e.message))},[]);
 if(error)return <Alert severity="error">{error}</Alert>; if(!o||!a||!servers||!dbs||!collection)return <CircularProgress />;
 const serverCards:ServerCardModel[]=servers.map(server=>{const items=dbs.filter(db=>db.serverId===server.serverId);const critical=items.filter(db=>['OFFLINE','SUSPECT','RECOVERY_PENDING','EMERGENCY'].includes(db.databaseStatus.toUpperCase())).length;const warning=items.filter(db=>!['ONLINE','RESTORING','RECOVERING'].includes(db.databaseStatus.toUpperCase())&&critical===0).length;const healthy=items.length-critical-warning;const status:ServerCardModel['status']=critical?'Critical':warning||!items.length?'Warning':'Healthy';const totalSize=items.reduce((sum,db)=>sum+(db.currentTotalSizeMb||0),0);return {...server,items,critical,warning,healthy,status,totalSize};}).sort((a,b)=>({Critical:0,Warning:1,Healthy:2}[a.status]-{Critical:0,Warning:1,Healthy:2}[b.status])||b.critical-a.critical);
 return <Stack spacing={3}><PageHeader title="SQL Estate Overview" subtitle="Sunucu filosu, veritabanı sağlığı ve operasyonel riskler"/><Box className="metric-grid"><Metric label="Sunucular" value={serverCards.length} tone="success"/><Metric label="Veritabanları" value={dbs.length}/><Metric label="Sağlıklı DB" value={dbs.filter(x=>x.databaseStatus==='ONLINE').length} tone="success"/><Metric label="Uyarı" value={o.warningEntityCount} tone={o.warningEntityCount?'warning':'success'}/><Metric label="Kritik" value={o.criticalEntityCount} tone={o.criticalEntityCount?'error':'success'}/><Metric label="Son Collection" value={collection.lastCollectionStatus||'N/A'} tone={collection.lastCollectionStatus==='Success'?'success':'warning'}/></Box><Box><ServerFleet servers={serverCards} onServer={onServer}/></Box><Box className="two-col"><SectionCard title="Yönetim Özeti" subtitle="İlişkili sinyaller ve aktif riskler"><Typography>{o.summary}</Typography><Stack direction="row" spacing={3} sx={{mt:2}}><Typography><b>{o.attentionEntityCount}</b><br/><Typography component="span" variant="caption" color="text.secondary">İlgilenilmesi gereken</Typography></Typography><Typography><b>{o.activeAnomalies}</b><br/><Typography component="span" variant="caption" color="text.secondary">Aktif anomali</Typography></Typography><Typography><b>{o.relatedSignalGroups}</b><br/><Typography component="span" variant="caption" color="text.secondary">Sinyal grubu</Typography></Typography></Stack></SectionCard><SectionCard title="Collection Durumu"><Typography color="text.secondary">Son tamamlanma</Typography><Typography variant="h6" sx={{mt:.5}}>{date(collection.lastCollectionFinishedAtUtc)}</Typography><Typography color="text.secondary" sx={{mt:1}}>Çalışma süresi: {collection.lastCollectionDurationMs??'N/A'} ms · Hata: {collection.collectionErrorCount}</Typography></SectionCard></Box><SectionCard title="Estate Health" subtitle="Sunucu ve veritabanı seviyesinde domain sağlık görünümü"><Table size="small"><TableHead><TableRow><TableCell>Entity</TableCell><TableCell>Overall</TableCell><TableCell>Performance</TableCell><TableCell>Protection</TableCell><TableCell>Availability</TableCell><TableCell>Capacity</TableCell><TableCell>Anomaly</TableCell></TableRow></TableHead><TableBody>{h.map(x=><TableRow key={x.entityType+'-'+x.serverId+'-'+(x.databaseId??0)} hover className="clickable" onClick={()=>x.databaseId&&onDatabase(x.databaseId)}><TableCell>{x.databaseName||x.serverName}</TableCell><TableCell><State value={x.overallStatus}/></TableCell><TableCell><State value={x.performanceStatus}/></TableCell><TableCell><State value={x.protectionStatus}/></TableCell><TableCell><State value={x.availabilityStatus}/></TableCell><TableCell><State value={x.capacityStatus}/></TableCell><TableCell><State value={x.anomalyStatus}/></TableCell></TableRow>)}</TableBody></Table></SectionCard><SectionCard title="Needs Attention" subtitle="Sorted by severity, then last seen"><Table size="small"><TableHead><TableRow><TableCell>Severity</TableCell><TableCell>Entity</TableCell><TableCell>Domain</TableCell><TableCell>Issue</TableCell><TableCell>Started</TableCell><TableCell>Last Seen</TableCell><TableCell>Related Signals</TableCell></TableRow></TableHead><TableBody>{a.items.map(x=><TableRow key={x.id}><TableCell><State value={x.severity}/></TableCell><TableCell>{x.databaseName||x.serverName}</TableCell><TableCell>{x.domain}</TableCell><TableCell>{x.issue}<Typography variant="caption" display="block" color="text.secondary">{x.explanationCode}</Typography></TableCell><TableCell>{date(x.startedAtUtc)}</TableCell><TableCell>{date(x.lastSeenAtUtc)}</TableCell><TableCell>{x.relatedSignalCount}</TableCell></TableRow>)}</TableBody></Table>{!a.items.length&&o.unknownEntityCount===0&&<EmptyState title="No active risks detected"/>}{!a.items.length&&o.unknownEntityCount>0&&<EmptyState title="Health cannot be fully determined" description="Telemetry is incomplete or stale."/>}</SectionCard></Stack>;
}function Dashboard({ onDatabase }: {onDatabase:(id:number)=>void}) {
  const [data, setData] = useState<{overview:Overview;health:Health[];capacity:Capacity;collections:Collection[]}>(); const [error, setError] = useState('');
  useEffect(() => { Promise.all([get<Overview>('/dashboard/overview'), get<Health[]>('/dashboard/database-health'), get<Capacity>('/dashboard/capacity'), get<Collection[]>('/collections/recent?limit=10')]).then(([overview,health,capacity,collections]) => setData({overview,health,capacity,collections})).catch(e => setError(e.message)); }, []);
  if (error) return <Alert severity="error">{error}</Alert>; if (!data) return <CircularProgress />;
  const o = data.overview;
  const healthCounts = [{ name: 'Healthy', value: data.health.filter(x => x.healthStatus === 'Healthy' || x.healthStatus === 'ONLINE').length, color: '#4dcc8a' }, { name: 'Warning', value: data.health.filter(x => x.healthStatus === 'Warning').length, color: '#e9aa4c' }, { name: 'Critical', value: data.health.filter(x => x.healthStatus === 'Critical').length, color: '#ed6a75' }].filter(x => x.value > 0);
  const collectionDurations = data.collections.filter(x => x.durationMs != null);
  return <Stack spacing={3}><Box><Typography variant="h4">Dashboard</Typography><Typography color="text.secondary">Database Operations Intelligence Platform</Typography></Box><Box className="metric-grid"><Metric label="Servers" value={o.totalServers}/><Metric label="Databases" value={o.totalDatabases}/><Metric label="Healthy" value={o.onlineDatabases} tone="success"/><Metric label="Warning / Critical" value={o.warningDatabases + o.offlineDatabases} tone={o.offlineDatabases ? 'error' : 'warning'}/><Metric label="Collection" value={o.lastCollectionStatus || 'N/A'} tone={o.lastCollectionStatus === 'Success' ? 'success' : 'warning'}/></Box><Box className="two-col"><Paper className="panel"><Typography variant="h6">Database Health</Typography><Divider/><Table size="small"><TableHead><TableRow><TableCell>Database</TableCell><TableCell>Server</TableCell><TableCell>Status</TableCell></TableRow></TableHead><TableBody>{data.health.map(x => <TableRow hover key={x.databaseId} onClick={() => onDatabase(x.databaseId)} className="clickable"><TableCell>{x.databaseName}</TableCell><TableCell>{x.serverName}</TableCell><TableCell><State value={x.healthStatus}/></TableCell></TableRow>)}</TableBody></Table></Paper><Paper className="panel"><Typography variant="h6">Capacity</Typography><Divider/><Stack spacing={1} sx={{mt:2}}><Typography>Data <b>{mb(data.capacity.summary.totalDataSizeMb)}</b></Typography><Typography>Log <b>{mb(data.capacity.summary.totalLogSizeMb)}</b></Typography><Typography>Total <b>{mb(data.capacity.summary.totalDatabaseSizeMb)}</b></Typography></Stack><Typography variant="h6" sx={{mt:3}}>Collection</Typography><Typography color="text.secondary">Last run: {date(o.lastCollectionFinishedAtUtc)}</Typography><Typography color="text.secondary">Duration: {o.lastCollectionDurationMs ?? 'N/A'} ms · Errors: {o.collectionErrorCount}</Typography></Paper></Box><Paper className="panel"><Typography variant="h6">Recent Collections</Typography><Divider/><Table size="small"><TableHead><TableRow><TableCell>Started</TableCell><TableCell>Finished</TableCell><TableCell>Status</TableCell><TableCell>Duration</TableCell><TableCell>Errors</TableCell></TableRow></TableHead><TableBody>{data.collections.map(x => <TableRow key={x.collectionRunId}><TableCell>{date(x.startedAtUtc)}</TableCell><TableCell>{date(x.finishedAtUtc)}</TableCell><TableCell><State value={x.status}/></TableCell><TableCell>{x.durationMs ?? 'N/A'} ms</TableCell><TableCell>{x.errorCount}</TableCell></TableRow>)}</TableBody></Table></Paper></Stack>;
}

function Estate({ onDatabase }: {onDatabase:(id:number)=>void}) {
  const [servers,setServers]=useState<Server[]>(); const [dbs,setDbs]=useState<Database[]>(); const [size,setSize]=useState(10); const [selectedServerId,setSelectedServerId]=useState<number>(); const [error,setError]=useState('');
  useEffect(()=>{Promise.all([get<Server[]>('/servers'),get<{items:Database[]}>('/databases?page=1&pageSize=100')]).then(([s,d])=>{setServers(s);setDbs(d.items);setSelectedServerId(current=>current ?? s[0]?.serverId)}).catch(e=>setError(e.message))},[]);
  if(error)return <Alert severity="error">{error}</Alert>; if(!servers||!dbs)return <CircularProgress/>;
  const visibleDbs=dbs.slice(0,size);
  return <Stack spacing={3}><Typography variant="h4">SQL Estate</Typography><Typography color="text.secondary">Sunucuları seçin; sağ panelde server kapsamındaki operasyonel verileri sekmelerle inceleyin.</Typography><Box className="estate-layout"><Paper className="panel estate-server-nav"><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="h6">Servers</Typography><Chip size="small" label={servers.length}/></Stack><Divider sx={{my:1.5}}/><List disablePadding>{servers.map(server=><ListItemButton key={server.serverId} selected={selectedServerId===server.serverId} onClick={()=>setSelectedServerId(server.serverId)}><ListItemText primary={server.serverName} secondary={`${server.databaseCount} database · ${date(server.lastSeenAtUtc)}`}/><StatusChip value={server.isActive === false ? 'Unknown' : 'Healthy'}/></ListItemButton>)}</List></Paper><Box className="estate-workspace">{selectedServerId ? <ServerWorkspace serverId={selectedServerId} onDatabase={onDatabase}/> : <EmptyState title="Select a server" description="Choose a server from the list to inspect its data."/>}</Box></Box><Paper className="panel"><Typography variant="h6">Databases</Typography><Divider/><ListTools filename="databases" rows={dbs} pageSize={size} onPageSizeChange={setSize}/><Table><TableHead><TableRow><TableCell>Database</TableCell><TableCell>Server</TableCell><TableCell>Status</TableCell><TableCell>Recovery</TableCell><TableCell>Current Size</TableCell></TableRow></TableHead><TableBody>{visibleDbs.map(d=><TableRow hover className="clickable" key={d.databaseId} onClick={()=>onDatabase(d.databaseId)}><TableCell>{d.databaseName}</TableCell><TableCell>{d.serverName}</TableCell><TableCell><State value={d.databaseStatus}/></TableCell><TableCell>{d.recoveryModel}</TableCell><TableCell>{mb(d.currentTotalSizeMb)}</TableCell></TableRow>)}</TableBody></Table></Paper></Stack>;
}
function ServerDetailView({ id, back, onDatabase }: {id:number;back:()=>void;onDatabase:(id:number)=>void}) { return <ServerWorkspace serverId={id} onDatabase={onDatabase} onBack={back} fullPage/>; }
function ButtonBack({onClick}:{onClick:()=>void}) { return <IconButton onClick={onClick} aria-label="Back"><ArrowBackIcon/></IconButton>; }

function DatabaseDetailView({ id, back }: {id:number;back:()=>void}) { const [data,setData]=useState<Detail>(); const [points,setPoints]=useState<Point[]>([]); const [days,setDays]=useState<ChartRange>(30); useEffect(()=>{Promise.all([get<Detail>(`/databases/${id}`),get<Point[]>(`/databases/${id}/capacity-history?days=${days}`)]).then(([d,p])=>{setData(d);setPoints(p)})},[id,days]);if(!data)return <CircularProgress/>;return <Stack spacing={3}><ButtonBack onClick={back}/><Typography variant="h4">{data.databaseName}</Typography><Paper className="panel"><Box className="detail-grid"><Typography>Server<br/><b>{data.serverName}</b></Typography><Typography>Status<br/><State value={data.databaseStatus}/></Typography><Typography>Recovery<br/><b>{data.recoveryModel}</b></Typography><Typography>Last Seen<br/><b>{date(data.lastSeenAtUtc)}</b></Typography></Box></Paper><Box className="metric-grid"><Metric label="Data" value={mb(data.currentDataSizeMb)}/><Metric label="Log" value={mb(data.currentLogSizeMb)}/><Metric label="Total" value={mb(data.currentTotalSizeMb)}/></Box><Paper className="panel"><Typography variant="h6">Backup</Typography><Typography>Full: {date(data.lastFullBackupAtSource)}</Typography><Typography>Differential: {date(data.lastDifferentialBackupAtSource)}</Typography><Typography>Log: {date(data.lastLogBackupAtSource)}</Typography></Paper><Paper className="panel"><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="h6">Capacity History</Typography><ChartToolbar value={days} ranges={[7,30,90]} onChange={setDays} /></Stack>{points.length ? <TimeSeriesChart categories={points.map(p=>date(p.collectedAtUtc))} series={[{name:'Data',data:points.map(p=>p.dataSizeMb),color:'#63a4ff',area:true},{name:'Log',data:points.map(p=>p.logSizeMb),color:'#e9aa4c',area:true},{name:'Total',data:points.map(p=>p.totalSizeMb),color:'#4dcc8a'}]} height={360} yAxisName="MiB" /> : <ChartEmptyState title="No capacity history available" description="Historical capacity telemetry has not been collected for this database." />}</Paper></Stack>; }
function AuditView() { const [items,setItems]=useState<Audit[]>([]); const [total,setTotal]=useState(0); const [page,setPage]=useState(1); const [pageSize,setPageSize]=useState(10); const [selected,setSelected]=useState<Audit>(); const [filters,setFilters]=useState({userName:'',action:'',resourceType:'',result:'',fromUtc:'',toUtc:''}); const [error,setError]=useState(''); useEffect(()=>{const p=new URLSearchParams({page:String(page),pageSize:String(pageSize)}); Object.entries(filters).forEach(([k,v])=>{if(v)p.set(k, k.endsWith('Utc') ? new Date(v).toISOString() : v)}); get<{items:Audit[];totalCount:number}>(`/audit?${p}`).then(x=>{setItems(x.items);setTotal(x.totalCount)}).catch(e=>setError(e.message))},[page,pageSize,filters]); if(error)return <Alert severity="error">{error}</Alert>; return <Stack spacing={3}><Box><Typography variant="h4">Audit</Typography><Typography color="text.secondary">Access and business activity history</Typography></Box><Paper className="panel"><Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap><TextField size="small" label="User" value={filters.userName} onChange={e=>{setPage(1);setFilters({...filters,userName:e.target.value})}}/><TextField size="small" label="Action" value={filters.action} onChange={e=>{setPage(1);setFilters({...filters,action:e.target.value})}}/><Select size="small" displayEmpty value={filters.resourceType} onChange={e=>{setPage(1);setFilters({...filters,resourceType:e.target.value})}}><MenuItem value="">Resource</MenuItem><MenuItem value="Dashboard">Dashboard</MenuItem><MenuItem value="Server">Server</MenuItem><MenuItem value="Database">Database</MenuItem><MenuItem value="Collection">Collection</MenuItem><MenuItem value="Audit">Audit</MenuItem></Select><Select size="small" displayEmpty value={filters.result} onChange={e=>{setPage(1);setFilters({...filters,result:e.target.value})}}><MenuItem value="">Result</MenuItem><MenuItem value="Success">Success</MenuItem><MenuItem value="Failed">Failed</MenuItem><MenuItem value="Denied">Denied</MenuItem></Select><TextField size="small" type="datetime-local" label="From" InputLabelProps={{shrink:true}} value={filters.fromUtc} onChange={e=>{setPage(1);setFilters({...filters,fromUtc:e.target.value})}}/><TextField size="small" type="datetime-local" label="To" InputLabelProps={{shrink:true}} value={filters.toUtc} onChange={e=>{setPage(1);setFilters({...filters,toUtc:e.target.value})}}/></Stack></Paper><Paper className="panel"><ListTools filename="audit" rows={items} pageSize={pageSize} onPageSizeChange={size=>{setPageSize(size);setPage(1)}}/><Table size="small"><TableHead><TableRow><TableCell>Time</TableCell><TableCell>User</TableCell><TableCell>Action</TableCell><TableCell>Resource</TableCell><TableCell>Result</TableCell><TableCell>Duration</TableCell><TableCell>Correlation ID</TableCell></TableRow></TableHead><TableBody>{items.map(x=><TableRow hover className="clickable" key={x.id} onClick={()=>setSelected(x)}><TableCell>{date(x.occurredAtUtc)}</TableCell><TableCell>{x.userName}</TableCell><TableCell>{x.action}</TableCell><TableCell>{x.resourceType}{x.resourceId ? `/${x.resourceId}` : ''}</TableCell><TableCell><State value={x.result}/></TableCell><TableCell>{x.durationMs} ms</TableCell><TableCell>{x.correlationId}</TableCell></TableRow>)}</TableBody></Table><Stack direction="row" justifyContent="space-between" sx={{mt:2}}><Typography color="text.secondary">{total} kayıt · Sayfa {page}</Typography><Stack direction="row" spacing={1}><Button disabled={page<=1} onClick={()=>setPage(page-1)}>Önceki</Button><Button disabled={page*pageSize>=total} onClick={()=>setPage(page+1)}>Sonraki</Button></Stack></Stack></Paper>{selected&&<Paper className="panel"><Stack direction="row" justifyContent="space-between"><Typography variant="h6">Audit Detail</Typography><Button onClick={()=>setSelected(undefined)}>Kapat</Button></Stack><Divider/><Box className="detail-grid" sx={{mt:2}}><Typography>Time<br/><b>{date(selected.occurredAtUtc)}</b></Typography><Typography>User / Role<br/><b>{selected.userName} / {selected.userRole || 'N/A'}</b></Typography><Typography>Method / Path<br/><b>{selected.httpMethod} {selected.requestPath}</b></Typography><Typography>Status / Duration<br/><b>{selected.statusCode} / {selected.durationMs} ms</b></Typography><Typography>Client IP<br/><b>{selected.clientIp || 'N/A'}</b></Typography><Typography>User Agent<br/><b>{selected.userAgent || 'N/A'}</b></Typography></Box>{selected.additionalData&&<Typography sx={{mt:2}}>Additional Data: {selected.additionalData}</Typography>}</Paper>}</Stack>; }

function PerformanceView() {
  const { selectedServerId, servers } = useServerFilter();
  const [data, setData] = useState<{overview:PerformanceOverview; blocking:Blocking[]; deadlocks:Deadlock[]; longRunning:LongRunning[]; waits:Wait[]}>();
  const [waitPage, setWaitPage] = useState(1); const [listSize, setListSize] = useState(10);
  const [error, setError] = useState('');
  useEffect(() => { Promise.all([get<PerformanceOverview>('/performance/overview?hours=24'), get<Blocking[]>('/performance/blocking?hours=24'), get<Deadlock[]>('/performance/deadlocks?hours=24'), get<LongRunning[]>('/performance/long-running?hours=24'), get<Wait[]>('/performance/waits?hours=24')]).then(([overview,blocking,deadlocks,longRunning,waits]) => setData({overview,blocking,deadlocks,longRunning,waits})).catch(e => setError(e.message)); }, []);
  if (error) return <Alert severity="error">{error}</Alert>;
  if (!data) return <CircularProgress />;
  const selectedServerName = selectedServerId ? servers.find(server => server.serverId === selectedServerId)?.serverName : undefined;
  const blocking = selectedServerName ? data.blocking.filter(row => row.serverName === selectedServerName) : data.blocking;
  const deadlocks = selectedServerName ? data.deadlocks.filter(row => row.serverName === selectedServerName) : data.deadlocks;
  const longRunning = selectedServerName ? data.longRunning.filter(row => row.serverName === selectedServerName) : data.longRunning;
  const overview = selectedServerName ? { ...data.overview, blockingObservationCount: blocking.length, maxBlockingDurationMs: Math.max(0, ...blocking.map(row => row.waitDurationMs)), deadlockCount: deadlocks.length, longRunningObservationCount: longRunning.length } : data.overview;
  const waitRows = data.waits.slice((waitPage - 1) * listSize, waitPage * listSize); const waitPageCount = Math.max(1, Math.ceil(data.waits.length / listSize));
  return <Stack spacing={3}><Box><Typography variant="h4">Performance</Typography><Typography color="text.secondary">{selectedServerName ? `${selectedServerName} · ` : ''}SQL telemetry · last 24 hours</Typography></Box><Box className="metric-grid"><Metric label="Blocking Observations" value={overview.blockingObservationCount}/><Metric label="Longest Blocking" value={`${overview.maxBlockingDurationMs} ms`} tone={overview.maxBlockingDurationMs ? 'warning' : 'success'}/><Metric label="Deadlocks" value={overview.deadlockCount} tone={overview.deadlockCount ? 'error' : 'success'}/><Metric label="Long Running Requests" value={overview.longRunningObservationCount} tone={overview.longRunningObservationCount ? 'warning' : 'success'}/></Box><Paper className="panel"><Typography variant="h6">Top Waits</Typography>{selectedServerName&&<Typography variant="caption" color="text.secondary">Wait API'sinde server kırılımı bulunmadığından bu bölüm fleet kapsamındadır.</Typography>}<Divider/>{data.waits.length ? <><HorizontalBarChart labels={data.waits.slice(0,listSize).map(x=>x.waitType)} values={data.waits.slice(0,listSize).map(x=>x.waitTimeDeltaMs)} valueName="Wait delta (ms)"/><Table size="small"><TableHead><TableRow><TableCell>Wait Type</TableCell><TableCell>Wait Delta</TableCell><TableCell>Signal Delta</TableCell><TableCell>Tasks</TableCell><TableCell>Percentage</TableCell></TableRow></TableHead><TableBody>{waitRows.map(x=><TableRow key={x.waitType}><TableCell>{x.waitType}</TableCell><TableCell>{x.waitTimeDeltaMs} ms</TableCell><TableCell>{x.signalWaitDeltaMs} ms</TableCell><TableCell>{x.waitingTasksDelta}</TableCell><TableCell>{x.percentage.toFixed(2)}%</TableCell></TableRow>)}</TableBody></Table><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{mt:2}}><Typography color="text.secondary">{data.waits.length} waits · Page {waitPage} / {waitPageCount}</Typography><Stack direction="row" spacing={1}><Button size="small" disabled={waitPage<=1} onClick={()=>setWaitPage(waitPage-1)}>Previous</Button><Button size="small" disabled={waitPage>=waitPageCount} onClick={()=>setWaitPage(waitPage+1)}>Next</Button></Stack></Stack></> : <ChartEmptyState title="No performance wait data available" description="Wait delta telemetry has not been collected for this period."/>}</Paper><Paper className="panel"><Typography variant="h6">Recent Blocking</Typography><Divider/><ListTools filename="blocking" rows={blocking} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setWaitPage(1)}}/>{blocking.length ? <Table size="small"><TableHead><TableRow><TableCell>Time</TableCell><TableCell>Server / Database</TableCell><TableCell>Session</TableCell><TableCell>Blocked By</TableCell><TableCell>Wait</TableCell><TableCell>Application</TableCell></TableRow></TableHead><TableBody>{blocking.slice(0,listSize).map(x=><TableRow key={x.id}><TableCell>{date(x.capturedAtUtc)}</TableCell><TableCell>{x.serverName} / {x.databaseName || 'N/A'}</TableCell><TableCell>{x.sessionId}</TableCell><TableCell>{x.blockingSessionId}</TableCell><TableCell>{x.waitType || 'N/A'} · {x.waitDurationMs} ms</TableCell><TableCell>{x.applicationName || 'N/A'}</TableCell></TableRow>)}</TableBody></Table> : <ChartEmptyState title="No blocking observations" description="No active blocking telemetry was observed in this period."/>}</Paper><Box className="two-col"><Paper className="panel"><Typography variant="h6">Deadlocks</Typography><Divider/><ListTools filename="deadlocks" rows={deadlocks} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setWaitPage(1)}}/>{deadlocks.length ? deadlocks.slice(0,listSize).map(x=><Typography key={x.id} sx={{mt:1}}>{date(x.occurredAtUtc)} · {x.serverName} · {x.processCount} processes</Typography>) : <ChartEmptyState title="No deadlocks observed" description="Zero is a real observation for this period."/>}</Paper><Paper className="panel"><Typography variant="h6">Long Running Requests</Typography><Divider/><ListTools filename="long-running" rows={longRunning} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setWaitPage(1)}}/>{longRunning.length ? longRunning.slice(0,listSize).map(x=><Typography key={x.id} sx={{mt:1}}>{date(x.capturedAtUtc)} · {x.serverName} / {x.databaseName || 'N/A'} · {x.elapsedMs} ms</Typography>) : <ChartEmptyState title="No long-running requests" description="No long-running request telemetry was observed in this period."/>}</Paper></Box></Stack>;
}

function OperationsView() {
  const { selectedServerId } = useServerFilter();
  const [overview,setOverview]=useState<OperationsOverview>(); const [items,setItems]=useState<OperationalEvent[]>([]); const [total,setTotal]=useState(0); const [page,setPage]=useState(1); const [pageSize,setPageSize]=useState(10); const [selected,setSelected]=useState<OperationalDetail>(); const [filters,setFilters]=useState({status:'',severity:'',eventType:''}); const [error,setError]=useState('');
  useEffect(()=>{get<OperationsOverview>('/operations/overview?hours=24').then(setOverview).catch(e=>setError(e.message))},[]);
  useEffect(()=>{const p=new URLSearchParams({page:String(page),pageSize:String(pageSize)});Object.entries(filters).forEach(([k,v])=>v&&p.set(k,v));if(selectedServerId)p.set('serverId',String(selectedServerId));get<{items:OperationalEvent[];totalCount:number}>(`/operations/events?${p}`).then(x=>{setItems(x.items);setTotal(x.totalCount)}).catch(e=>setError(e.message))},[page,pageSize,filters,selectedServerId]);
  if(error)return <Alert severity="error">{error}</Alert>;if(!overview)return <CircularProgress/>;
  return <Stack spacing={3}><Box><Typography variant="h4">Operations</Typography><Typography color="text.secondary">Operational events · last 24 hours</Typography></Box><Box className="metric-grid"><Metric label="Active Events" value={overview.activeEventCount}/><Metric label="Critical" value={overview.activeCriticalCount} tone={overview.activeCriticalCount?'error':'success'}/><Metric label="Warning" value={overview.activeWarningCount} tone={overview.activeWarningCount?'warning':'success'}/><Metric label="Resolved" value={overview.resolvedEventCount}/></Box><Paper className="panel"><Typography variant="h6">Event Types</Typography><Divider/><Stack direction="row" spacing={3} sx={{mt:2}}><Typography>Blocking <b>{overview.blockingEventCount}</b></Typography><Typography>Long Running <b>{overview.longRunningEventCount}</b></Typography><Typography>Deadlock <b>{overview.deadlockEventCount}</b></Typography></Stack></Paper><Paper className="panel"><Stack direction="row" spacing={1} flexWrap="wrap"><Select size="small" displayEmpty value={filters.status} onChange={e=>{setPage(1);setFilters({...filters,status:e.target.value})}}><MenuItem value="">Status</MenuItem><MenuItem value="Active">Active</MenuItem><MenuItem value="Resolved">Resolved</MenuItem></Select><Select size="small" displayEmpty value={filters.severity} onChange={e=>{setPage(1);setFilters({...filters,severity:e.target.value})}}><MenuItem value="">Severity</MenuItem><MenuItem value="Critical">Critical</MenuItem><MenuItem value="Warning">Warning</MenuItem><MenuItem value="Info">Info</MenuItem></Select><Select size="small" displayEmpty value={filters.eventType} onChange={e=>{setPage(1);setFilters({...filters,eventType:e.target.value})}}><MenuItem value="">Type</MenuItem><MenuItem value="Blocking">Blocking</MenuItem><MenuItem value="LongRunning">Long Running</MenuItem><MenuItem value="Deadlock">Deadlock</MenuItem></Select></Stack></Paper><Paper className="panel"><ListTools filename="operational-events" rows={items} pageSize={pageSize} onPageSizeChange={size=>{setPageSize(size);setPage(1)}}/><Table size="small"><TableHead><TableRow><TableCell>Severity</TableCell><TableCell>Status</TableCell><TableCell>Type</TableCell><TableCell>Started</TableCell><TableCell>Last Seen</TableCell><TableCell>Duration</TableCell><TableCell>Server / Database</TableCell><TableCell>Title</TableCell></TableRow></TableHead><TableBody>{items.map(x=><TableRow hover className="clickable" key={x.id} onClick={()=>get<OperationalDetail>(`/operations/events/${x.id}`).then(setSelected)}><TableCell><State value={x.severity}/></TableCell><TableCell><State value={x.status}/></TableCell><TableCell>{x.eventType}</TableCell><TableCell>{date(x.startedAtUtc)}</TableCell><TableCell>{date(x.lastSeenAtUtc)}</TableCell><TableCell>{x.durationMs} ms</TableCell><TableCell>{x.serverName} / {x.databaseName||'N/A'}</TableCell><TableCell>{x.title}</TableCell></TableRow>)}</TableBody></Table><Stack direction="row" justifyContent="space-between" sx={{mt:2}}><Typography color="text.secondary">{total} events · Page {page}</Typography><Stack direction="row"><Button disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</Button><Button disabled={page*pageSize>=total} onClick={()=>setPage(page+1)}>Next</Button></Stack></Stack></Paper>{selected&&<Paper className="panel"><Stack direction="row" justifyContent="space-between"><Typography variant="h6">Event Detail</Typography><Button onClick={()=>setSelected(undefined)}>Close</Button></Stack><Divider/><Box className="detail-grid" sx={{mt:2}}><Typography>Type / Status<br/><b>{selected.eventType} / {selected.status}</b></Typography><Typography>Severity<br/><State value={selected.severity}/></Typography><Typography>Server / Database<br/><b>{selected.serverName} / {selected.databaseName||'N/A'}</b></Typography><Typography>Duration<br/><b>{selected.durationMs} ms</b></Typography><Typography>Observations<br/><b>{selected.observationCount}</b></Typography><Typography>Affected Sessions<br/><b>{selected.affectedSessionCount??'N/A'}</b></Typography></Box><Typography sx={{mt:2}}>{selected.summary}</Typography></Paper>}</Stack>;
}

function InsightsView() {
  const { selectedServerId } = useServerFilter();
  const [overview,setOverview]=useState<AnomalyOverview>(); const [items,setItems]=useState<AnomalyRow[]>([]); const [total,setTotal]=useState(0); const [pageSize,setPageSize]=useState(10); const [selected,setSelected]=useState<AnomalyDetail>(); const [error,setError]=useState('');
  useEffect(()=>{const serverQuery=selectedServerId?`&serverId=${selectedServerId}`:'';Promise.all([get<AnomalyOverview>('/anomalies/overview'),get<{items:AnomalyRow[];totalCount:number}>(`/anomalies?status=Active&page=1&pageSize=50${serverQuery}`)]).then(([o,a])=>{setOverview(o);setItems(a.items);setTotal(a.totalCount)}).catch(e=>setError(e.message))},[selectedServerId]);
  if(error)return <Alert severity="error">Unable to load anomaly insights: {error}</Alert>; if(!overview)return <CircularProgress/>;
  const coverageTotal=overview.usableBaselineCount+overview.insufficientBaselineCount; const coverage=coverageTotal?`${Math.round(overview.usableBaselineCount/coverageTotal*100)}%`:'Insufficient data';
  return <Stack spacing={3}><PageHeader title="Insights" subtitle="Baseline-driven unusual activity across the SQL estate"/><Box className="metric-grid"><Metric label="Active Anomalies" value={overview.activeAnomalyCount}/><Metric label="Critical" value={overview.activeCriticalCount} tone={overview.activeCriticalCount?'error':'success'}/><Metric label="Warning" value={overview.activeWarningCount} tone={overview.activeWarningCount?'warning':'success'}/><Metric label="Baseline Coverage" value={coverage} tone={coverageTotal&&overview.usableBaselineCount?'success':undefined}/></Box><Paper className="panel"><Typography variant="h6">Unusual Activity</Typography><Divider/>{items.length?<><ListTools filename="anomalies" rows={items} pageSize={pageSize} onPageSizeChange={setPageSize}/><Table size="small"><TableHead><TableRow><TableCell>Severity</TableCell><TableCell>Metric</TableCell><TableCell>Server</TableCell><TableCell>Database / Entity</TableCell><TableCell>Observed</TableCell><TableCell>Median</TableCell><TableCell>P95</TableCell><TableCell>Scope</TableCell><TableCell>Last Seen</TableCell></TableRow></TableHead><TableBody>{items.map(item=><TableRow hover className="clickable" key={item.id} onClick={()=>get<AnomalyDetail>(`/anomalies/${item.id}`).then(setSelected)}><TableCell><State value={item.severity}/></TableCell><TableCell>{item.metricType}</TableCell><TableCell>{item.serverName}</TableCell><TableCell>{item.databaseName||item.entityKey||'N/A'}</TableCell><TableCell>{item.observedValue.toLocaleString()}</TableCell><TableCell>{item.baselineMedian.toLocaleString()}</TableCell><TableCell>{item.baselineP95.toLocaleString()}</TableCell><TableCell>{item.baselineScope}</TableCell><TableCell>{date(item.lastSeenAtUtc)}</TableCell></TableRow>)}</TableBody></Table></>:<EmptyState title={overview.usableBaselineCount?'No unusual activity detected':'Insufficient baseline coverage'} description={overview.usableBaselineCount?'Active anomaly findings are empty.':'Historical telemetry does not yet provide enough samples for anomaly evaluation.'}/>}<Typography color="text.secondary" sx={{mt:2}}>{total} findings</Typography></Paper>{selected&&<Paper className="panel"><Stack direction="row" justifyContent="space-between"><Typography variant="h6">Anomaly Detail</Typography><Button onClick={()=>setSelected(undefined)}>Close</Button></Stack><Divider/><Box className="detail-grid" sx={{mt:2}}><Typography>Metric<br/><b>{selected.metricType}</b></Typography><Typography>Status / Severity<br/><State value={selected.status}/>{' '}<State value={selected.severity}/></Typography><Typography>Observed<br/><b>{selected.observedValue.toLocaleString()}</b></Typography><Typography>Median / P95 / P99<br/><b>{selected.baselineMedian.toLocaleString()} / {selected.baselineP95.toLocaleString()} / {selected.baselineP99.toLocaleString()}</b></Typography><Typography>MAD / Modified Z<br/><b>{selected.baselineMad.toLocaleString()} / {selected.modifiedZScore?.toFixed(2)??'N/A'}</b></Typography><Typography>Baseline<br/><b>{selected.baselineScope} · {selected.windowDays} days · {selected.sampleCount} samples</b></Typography><Typography>Explanation<br/><b>{selected.explanationCode}</b></Typography><Typography>Started / Last Seen<br/><b>{date(selected.startedAtUtc)} / {date(selected.lastSeenAtUtc)}</b></Typography></Box></Paper>}</Stack>;
}

function ProtectionView() {
  const { selectedServerId } = useServerFilter();
  const [overview,setOverview]=useState<ProtectionOverview>(); const [listSize,setListSize]=useState(10); const [backups,setBackups]=useState<Page<BackupProtection>>(); const [alwaysOn,setAlwaysOn]=useState<Page<AlwaysOnHealth>>(); const [jobs,setJobs]=useState<Page<JobHealth>>(); const [backupPage,setBackupPage]=useState(1); const [agPage,setAgPage]=useState(1); const [jobPage,setJobPage]=useState(1); const [error,setError]=useState('');
  useEffect(()=>{const serverQuery=selectedServerId?`&serverId=${selectedServerId}`:'';Promise.all([get<ProtectionOverview>('/protection/overview'),get<Page<BackupProtection>>(`/protection/backups?page=${backupPage}&pageSize=${listSize}${serverQuery}`),get<Page<AlwaysOnHealth>>(`/availability/alwayson?page=${agPage}&pageSize=${listSize}${serverQuery}`),get<Page<JobHealth>>(`/jobs?page=${jobPage}&pageSize=${listSize}${serverQuery}`)]).then(([o,b,a,j])=>{setOverview(o);setBackups(b);setAlwaysOn(a);setJobs(j)}).catch(e=>setError(e.message))},[backupPage,agPage,jobPage,listSize,selectedServerId]);
  if(error)return <Alert severity="error">{error}</Alert>; if(!overview||!backups||!alwaysOn||!jobs)return <CircularProgress/>;
  const pager=(page:number,total:number,setPage:(x:number)=>void)=><Stack direction="row" justifyContent="space-between" sx={{mt:1}}><Typography color="text.secondary">{total} records · Page {page} / {Math.max(1,Math.ceil(total/listSize))}</Typography><Stack direction="row"><Button size="small" disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</Button><Button size="small" disabled={page*listSize>=total} onClick={()=>setPage(page+1)}>Next</Button></Stack></Stack>;
  return <Stack spacing={3}><Box><Typography variant="h4">Protection &amp; Availability</Typography><Typography color="text.secondary">Backup protection, Always On availability and SQL Agent health</Typography></Box><Box className="metric-grid"><Metric label="Protected Databases" value={overview.protectedDatabaseCount} tone="success"/><Metric label="Backup Risk" value={overview.backupWarningCount+overview.backupCriticalCount} tone={overview.backupCriticalCount?'error':'warning'}/><Metric label="AG Warning" value={overview.alwaysOnWarningCount+overview.alwaysOnCriticalCount} tone={overview.alwaysOnCriticalCount?'error':'warning'}/><Metric label="Failed Jobs" value={overview.failedJobCount} tone={overview.failedJobCount?'error':'success'}/></Box><Paper className="panel"><Typography variant="h6">Backup Protection</Typography><Divider/><ListTools filename="backup-protection" rows={backups.items} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setBackupPage(1)}}/>{backups.items.length?<Table size="small"><TableHead><TableRow><TableCell>Status</TableCell><TableCell>Server / Database</TableCell><TableCell>Recovery</TableCell><TableCell>Last Full</TableCell><TableCell>Last Diff</TableCell><TableCell>Last Log</TableCell><TableCell>Age</TableCell></TableRow></TableHead><TableBody>{backups.items.map(x=><TableRow key={x.databaseId}><TableCell><State value={x.protectionStatus}/></TableCell><TableCell>{x.serverName} / {x.databaseName}</TableCell><TableCell>{x.recoveryModel}</TableCell><TableCell>{date(x.lastFullBackupAtSource)}</TableCell><TableCell>{date(x.lastDifferentialBackupAtSource)}</TableCell><TableCell>{date(x.lastLogBackupAtSource)}</TableCell><TableCell>{x.backupAgeMinutes==null?'N/A':`${x.backupAgeMinutes} min`}</TableCell></TableRow>)}</TableBody></Table>:<EmptyState title="No backup protection data available" description="Backup protection telemetry has not been collected."/>}{pager(backupPage,backups.totalCount,setBackupPage)}</Paper><Paper className="panel"><Typography variant="h6">Always On</Typography><Divider/><ListTools filename="always-on" rows={alwaysOn.items} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setAgPage(1)}}/>{alwaysOn.items.length?<Table size="small"><TableHead><TableRow><TableCell>Health</TableCell><TableCell>AG / Replica</TableCell><TableCell>Role</TableCell><TableCell>Database</TableCell><TableCell>Sync</TableCell><TableCell>Queues</TableCell></TableRow></TableHead><TableBody>{alwaysOn.items.map(x=><TableRow key={x.id}><TableCell><State value={x.healthStatus}/></TableCell><TableCell>{x.availabilityGroupName} / {x.replicaServerName||'N/A'}</TableCell><TableCell>{x.role||'N/A'}</TableCell><TableCell>{x.databaseName||'N/A'}</TableCell><TableCell>{x.synchronizationState||'N/A'} · {x.synchronizationHealth||'N/A'}</TableCell><TableCell>{x.logSendQueueMb??'N/A'} / {x.redoQueueMb??'N/A'} MB</TableCell></TableRow>)}</TableBody></Table>:<EmptyState title="Always On is not configured" description="Always On is not configured for this server."/>}{pager(agPage,alwaysOn.totalCount,setAgPage)}</Paper><Paper className="panel"><Typography variant="h6">SQL Agent Jobs</Typography><Divider/><ListTools filename="sql-agent-jobs" rows={jobs.items} pageSize={listSize} onPageSizeChange={size=>{setListSize(size);setJobPage(1)}}/>{jobs.items.length?<Table size="small"><TableHead><TableRow><TableCell>Status</TableCell><TableCell>Server / Job</TableCell><TableCell>Enabled</TableCell><TableCell>Last Run</TableCell><TableCell>Duration</TableCell><TableCell>Failures 24h / 7d</TableCell><TableCell>Running</TableCell></TableRow></TableHead><TableBody>{jobs.items.map(x=><TableRow key={x.id}><TableCell><State value={x.lastRunStatus}/></TableCell><TableCell>{x.serverName} / {x.jobName}</TableCell><TableCell>{x.enabled?'Yes':'No'}</TableCell><TableCell>{date(x.lastRunAtSource)}</TableCell><TableCell>{x.isRunning?`${x.currentDurationSeconds??0}s`:x.lastRunDurationSeconds==null?'N/A':`${x.lastRunDurationSeconds}s`}</TableCell><TableCell>{x.failureCount24Hours} / {x.failureCount7Days}</TableCell><TableCell>{x.isRunning?'Running':'No'}</TableCell></TableRow>)}</TableBody></Table>:<EmptyState title="No SQL Agent jobs found" description="No SQL Agent jobs are currently available in the management database."/>}{pager(jobPage,jobs.totalCount,setJobPage)}</Paper></Stack>;
}

function CapacityView() {
  const { selectedServerId, servers } = useServerFilter();
  const [overview, setOverview] = useState<CapacityOverview>();
  const [dbs, setDbs] = useState<Page<CapacityDb>>();
  const [volumes, setVolumes] = useState<Page<VolumeCapacity>>();
  const [listSize, setListSize] = useState(10);
  const [page, setPage] = useState(1);
  const [volumePage, setVolumePage] = useState(1);
  const [selected, setSelected] = useState<CapacityDb>();
  const [history, setHistory] = useState<CapacityPoint[]>([]);
  const [error, setError] = useState('');
  useEffect(() => {
    const query = selectedServerId ? '&serverId=' + selectedServerId : '';
    Promise.all([
      get<CapacityOverview>('/capacity/overview'),
      get<Page<CapacityDb>>('/capacity/databases?page=' + page + '&pageSize=100' + query),
      get<Page<VolumeCapacity>>('/capacity/volumes?page=' + volumePage + '&pageSize=10' + query)
    ]).then(([o, d, v]) => {
      setOverview(o);
      const selectedServerName = selectedServerId ? servers.find(server => server.serverId === selectedServerId)?.serverName : undefined;
      const visibleDbs = selectedServerName ? d.items.filter(item => item.serverName === selectedServerName) : d.items;
      const visibleVolumes = selectedServerName ? v.items.filter(item => item.serverName === selectedServerName) : v.items;
      setDbs(selectedServerName ? { ...d, items: visibleDbs, totalCount: visibleDbs.length } : d);
      setVolumes(selectedServerName ? { ...v, items: visibleVolumes, totalCount: visibleVolumes.length } : v);
      if (!selected && visibleDbs.length) setSelected([...visibleDbs].sort((a, b) => (b.growth30dMb ?? -Infinity) - (a.growth30dMb ?? -Infinity))[0]);
    }).catch(e => setError(e.message));
  }, [page, volumePage, selectedServerId, servers]);
  useEffect(() => { setSelected(undefined); setHistory([]); setPage(1); setVolumePage(1); }, [selectedServerId]);
  useEffect(() => {
    if (!selected) return;
    get<Page<CapacityDb>>('/capacity/databases/' + selected.databaseId).then(x => setSelected(x.items[0] || selected));
    get<CapacityPoint[]>('/capacity/databases/' + selected.databaseId + '/history?days=30').then(setHistory).catch(() => setHistory([]));
  }, [selected?.databaseId]);
  if (error) return <Alert severity="error">{error}</Alert>;
  if (!overview || !dbs || !volumes) return <CircularProgress />;
  const fmt = (v?: number | null) => v == null ? 'Insufficient data' : mb(v);
  const bytes = (v: number) => v >= 1099511627776 ? (v / 1099511627776).toFixed(1) + ' TiB' : v >= 1073741824 ? (v / 1073741824).toFixed(1) + ' GiB' : (v / 1048576).toFixed(1) + ' MiB';
  const visibleDbs = dbs.items.slice(0, listSize); const visibleVolumes = volumes.items.slice(0, listSize); const top = [...dbs.items].filter(x => x.growth30dMb != null).sort((a, b) => (b.growth30dMb ?? 0) - (a.growth30dMb ?? 0)).slice(0, 10);
  const anchor = history.length ? history[history.length - 1].collectedAtUtc : undefined;
  const last = history.length ? history[history.length - 1].totalSizeMb : (selected?.currentTotalSizeMb ?? 0);
  const target = selected?.forecast30dMb ?? last;
  const future = anchor ? Array.from({ length: 30 }, (_, i) => date(new Date(new Date(anchor).getTime() + (i + 1) * 86400000).toISOString())) : [];
  const categories = [...history.map(x => date(x.collectedAtUtc)), ...future];
  const actual = [...history.map(x => x.totalSizeMb), ...future.map(() => null)];
  const forecast = history.length ? [...history.slice(0, -1).map(() => null), last, ...Array.from({ length: 30 }, (_, i) => last + (target - last) * ((i + 1) / 30))] : [];
  const pager = (p: number, total: number, set: (n: number) => void) => <Stack direction="row" justifyContent="space-between" sx={{ mt: 1 }}><Typography color="text.secondary">{total} records - Page {p} / {Math.max(1, Math.ceil(total / 100))}</Typography><Stack direction="row"><Button size="small" disabled={p <= 1} onClick={() => set(p - 1)}>Previous</Button><Button size="small" disabled={p * 100 >= total} onClick={() => set(p + 1)}>Next</Button></Stack></Stack>;
  return <Stack spacing={3}>
    <PageHeader title="FinOps & Capacity" subtitle="Database growth, storage trend and capacity forecast" />
    <Box className="metric-grid"><Metric label="Total DB Size" value={mb(overview.totalDatabaseSizeMb)} /><Metric label="30d Growth" value={overview.growth30dMb == null ? 'Insufficient data' : '+' + mb(overview.growth30dMb)} tone={overview.growth30dMb && overview.growth30dMb > 0 ? 'warning' : 'success'} /><Metric label="Capacity Risk" value={overview.databaseWarningCount + overview.databaseCriticalCount + overview.volumeWarningCount + overview.volumeCriticalCount} tone={overview.databaseCriticalCount + overview.volumeCriticalCount ? 'error' : 'warning'} /><Metric label="Visible DBs" value={dbs.items.length} /></Box>
    <Box className="two-col"><Paper className="panel capacity-chart-panel"><Typography variant="h6">Growth Trend</Typography><Typography variant="body2" color="text.secondary">{selected ? selected.serverName + ' / ' + selected.databaseName : 'Select a database'} - actual and 30d forecast</Typography><Divider sx={{ my: 1.5 }} />{history.length ? <ForecastChart categories={categories} actual={actual} forecast30={forecast} height={360} /> : <EmptyState title="No capacity history available" description="Select a database with historical telemetry." />}</Paper><Paper className="panel capacity-chart-panel"><Typography variant="h6">Top Growing Databases</Typography><Typography variant="body2" color="text.secondary">{selectedServerId ? 'Selected server' : 'All servers'} - last 30 days</Typography><Divider sx={{ my: 1.5 }} />{top.length ? <><HorizontalBarChart labels={top.map(x => x.databaseName)} values={top.map(x => x.growth30dMb ?? 0)} valueName="Growth (MB)" height={260} onClick={i => { setSelected(top[i]); setHistory([]); }} /><Stack className="growth-rank-list" spacing={0.5}>{top.slice(0, 5).map((x, i) => <Stack direction="row" justifyContent="space-between" key={x.databaseId}><Typography variant="caption" noWrap>{i + 1}. {x.serverName} / {x.databaseName}</Typography><Typography variant="caption" color="warning.main">+{fmt(x.growth30dMb)}</Typography></Stack>)}</Stack></> : <EmptyState title="Insufficient growth history" />}</Paper></Box>
    <Paper className="panel"><Stack direction="row" justifyContent="space-between" alignItems="center"><Box><Typography variant="h6">Database Growth</Typography><ListTools filename="database-growth" rows={dbs.items} pageSize={listSize} onPageSizeChange={setListSize}/><Typography variant="body2" color="text.secondary">{dbs.totalCount} databases - click a row to update the trend chart</Typography></Box><Chip size="small" label={selectedServerId ? 'Server filtered' : 'Fleet view'} variant="outlined" /></Stack><Divider sx={{ my: 1.5 }} />{dbs.items.length ? <Table size="small"><TableHead><TableRow><TableCell>Status</TableCell><TableCell>Server / Database</TableCell><TableCell>Current</TableCell><TableCell>Growth 7d</TableCell><TableCell>Growth 30d</TableCell><TableCell>Rate / Day</TableCell><TableCell>Forecast 30d / 90d</TableCell></TableRow></TableHead><TableBody>{visibleDbs.map(x => <TableRow hover className="clickable" key={x.databaseId} selected={selected?.databaseId === x.databaseId} onClick={() => { setSelected(x); setHistory([]); }}><TableCell><State value={x.forecastStatus} /></TableCell><TableCell>{x.serverName} / {x.databaseName}</TableCell><TableCell>{mb(x.currentTotalSizeMb)}</TableCell><TableCell>{fmt(x.growth7dMb)}</TableCell><TableCell>{fmt(x.growth30dMb)}</TableCell><TableCell>{fmt(x.growthRateMbPerDay)}</TableCell><TableCell>{fmt(x.forecast30dMb)} / {fmt(x.forecast90dMb)}</TableCell></TableRow>)}</TableBody></Table> : <EmptyState title="No capacity data available" description="No databases match the selected server." />}{dbs.totalCount > 100 && pager(page, dbs.totalCount, setPage)}</Paper>
    <Paper className="panel"><Typography variant="h6">Volume Capacity</Typography><ListTools filename="volume-capacity" rows={volumes.items} pageSize={listSize} onPageSizeChange={setListSize}/><Divider sx={{ my: 1.5 }} />{volumes.items.length ? <Table size="small"><TableHead><TableRow><TableCell>Status</TableCell><TableCell>Server / Volume</TableCell><TableCell>Total</TableCell><TableCell>Available</TableCell><TableCell>Free %</TableCell><TableCell>Exhaustion</TableCell></TableRow></TableHead><TableBody>{visibleVolumes.map(x => <TableRow key={x.id}><TableCell><State value={x.capacityStatus} /></TableCell><TableCell>{x.serverName} / {x.volumeId}</TableCell><TableCell>{bytes(x.totalBytes)}</TableCell><TableCell>{bytes(x.availableBytes)}</TableCell><TableCell>{x.freePercent}%</TableCell><TableCell>{x.estimatedExhaustionDays == null ? 'Not forecastable' : x.estimatedExhaustionDays.toFixed(0) + ' days'}</TableCell></TableRow>)}</TableBody></Table> : <EmptyState title="No volume data available" description="No volume data matches the selected server." />}{pager(volumePage, volumes.totalCount, setVolumePage)}</Paper>
  </Stack>;
}
export default function App() {
  const requestedView = new URLSearchParams(window.location.search).get('view');
  const [view, setView] = useState<'dashboard'|'estate'|'server'|'database'|'audit'|'performance'|'operations'|'protection'|'capacity'|'insights'>(requestedView === 'audit' ? 'audit' : requestedView === 'performance' ? 'performance' : requestedView === 'operations' ? 'operations' : requestedView === 'protection' ? 'protection' : requestedView === 'capacity' ? 'capacity' : requestedView === 'insights' ? 'insights' : 'dashboard');
  const [id, setId] = useState(0);
  const openDatabase = (x:number) => { setId(x); setView('database'); };
  const openServer = (x:number) => { setId(x); setView('server'); };
  const navigate = (next: string) => setView((next === 'collections' ? 'dashboard' : next) as typeof view);
  return <AppShell activeView={view} onNavigate={navigate} onServerSelect={openServer}>{view === 'dashboard' && <ManagementDashboard onDatabase={openDatabase} onServer={openServer} />} {view === 'estate' && <Estate onDatabase={openDatabase} />} {view === 'server' && <ServerDetailView id={id} back={() => setView('estate')} onDatabase={openDatabase} />} {view === 'database' && <DatabaseDetailView id={id} back={() => setView('estate')} />} {view === 'protection' && <ProtectionView />} {view === 'capacity' && <CapacityView />} {view === 'performance' && <PerformanceView />} {view === 'operations' && <OperationsView />} {view === 'insights' && <InsightsView />} {view === 'audit' && <AuditView />}</AppShell>;
}
